  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st2', 10, 4, 'category', 'Phân loại đúng nhóm', 'Vận dụng kiến thức để quan sát cơ thể đơn bào và nhận diện các cấp tổ chức của cơ thể đa bào.', '{"categories":["Đối tượng quan sát trực tiếp","Dụng cụ hoặc mô hình hỗ trợ"],"items":["Mẫu nước ao","Cây có hoa","Kính hiển vi","Mô hình giải phẫu"],"hint":"Phân biệt hai nhóm “Đối tượng quan sát trực tiếp” và “Dụng cụ hoặc mô hình hỗ trợ” theo đặc điểm của từng mục. “Mẫu nước ao” thuộc nhóm “Đối tượng quan sát trực tiếp”."}'::jsonb, '{"value":[{"name":"Mẫu nước ao","catIndex":0},{"name":"Cây có hoa","catIndex":0},{"name":"Kính hiển vi","catIndex":1},{"name":"Mô hình giải phẫu","catIndex":1}],"explanation":"Mẫu nước ao thuộc nhóm Đối tượng quan sát trực tiếp; Cây có hoa thuộc nhóm Đối tượng quan sát trực tiếp; Kính hiển vi thuộc nhóm Dụng cụ hoặc mô hình hỗ trợ; Mô hình giải phẫu thuộc nhóm Dụng cụ hoặc mô hình hỗ trợ."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 3-4. Thực hành và ôn tập Chương VI","pages":"100-104"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 6, 'g6_st2', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Vận dụng kiến thức để quan sát cơ thể đơn bào và nhận diện các cấp tổ chức của cơ thể đa bào.', '{"textWithBlanks":"Tế bào → mô → cơ quan → hệ cơ quan → [blank].","bankWords":["cơ thể","vi khuẩn","khoáng vật"],"hint":"Thử từng từ trong kho vào câu “Tế bào → mô → cơ quan → hệ cơ quan → [blank].” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “c” và gồm 2 tiếng."}'::jsonb, '{"value":"cơ thể","explanation":"Từ đúng là “cơ thể”."}'::jsonb, '[{"source":"SGK Khoa học tự nhiên 6 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 3-4. Thực hành và ôn tập Chương VI","pages":"100-104"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
end;
